#include "short.h"

static int digit(char c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'z') return c - 'a' + 10;
  if (c >= 'A' && c <= 'Z') return c - 'A' + 36;
  return -1;
}

int short_decode(const char *s, uint64_t *out) {
  if (s == NULL || *s == '\0') return -1;
  uint64_t n = 0;
  for (; *s; s++) {
    int d = digit(*s);
    if (d < 0) return -1;
    if (n > (UINT64_MAX - (uint64_t)d) / 62) return -1;
    n = n * 62 + (uint64_t)d;
  }
  *out = n;
  return 0;
}
